fn create_row(n: u8) -> Vec<u8> {
    // Create a vector with capacity n to hold values 0..n-1
    let mut row = Vec::with_capacity(n as usize);
    // Iterate from 0 to n-1 and push each value into the row
    for i in 0..n {
        row.push(i);
    }
    row
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    // Construct a grid with exactly one row
    vec![create_row(n)]
}

